package io.github.eschizoid.telescope.demo.nativeimage;

import io.github.eschizoid.telescope.jackson.FromJson;

/**
 * A carrier's scan of a parcel, posted as JSON. Its binder is generated by {@code @FromJson}, and
 * the record has no reflection registration: the generated binder calls its constructor in source.
 */
@FromJson
public record CarrierScan(String trackingNumber, String city, int attempt) {}
